  const label = document.createElement('label'); label.htmlFor = 'task-title'; label.textContent = 'Task title';
  const input = document.createElement('input'); input.id = 'task-title'; input.type = 'text'; input.setAttribute('aria-label', 'Task title');
  const create = document.createElement('button'); create.type = 'submit'; create.textContent = 'Create task';
  form.append(label, input, create); app.append(form);
  const alert = document.createElement('p'); alert.id = 'alert'; alert.setAttribute('role', 'alert'); app.append(alert);
  const filterLabel = document.createElement('label'); filterLabel.htmlFor = 'task-filter'; filterLabel.textContent = 'Task filter'; app.append(filterLabel);
  const filter = document.createElement('select'); filter.id = 'task-filter';
  for (const value of ['All', 'Open', 'Completed']) { const option = document.createElement('option'); option.textContent = value; option.value = value; filter.append(option); }
  app.append(filter);
  const list = document.createElement('ul'); list.id = 'tasks'; app.append(list);
  async function load() {
    const tasks = await request(`/api/projects/${escapePath(id)}/tasks`);
    list.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed || filter.value === 'Completed' && !task.completed) continue;
      const row = document.createElement('li'); row.dataset.testid = 'task-row';
      const checkbox = document.createElement('input'); checkbox.type = 'checkbox'; checkbox.checked = Boolean(task.completed); checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => { try { await request(`/api/projects/${escapePath(id)}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) }); await load(); } catch (error) { alert.textContent = error.message; } });
      const title = document.createElement('span'); title.textContent = task.title;
      row.append(checkbox, title); list.append(row);
    }
  }
  filter.addEventListener('change', () => load().catch(error => { alert.textContent = error.message; }));
  form.addEventListener('submit', async event => {
    event.preventDefault(); alert.textContent = '';
    if (!input.value.trim()) { alert.textContent = 'Task title is required'; return; }
    try { await request(`/api/projects/${escapePath(id)}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title: input.value }) }); input.value = ''; await load(); }
    catch (error) { alert.textContent = error.message; }
  });
  await load();
}

